function renderResultLists(){const box=$('#resultPeopleList'),un=$('#unassignedList');if(!box||!un)return;const byPerson=new Map(displayAssignments().map(([seat,pid])=>[pid,seat])),q=resultFilter.query.trim().toLowerCase();box.innerHTML='';un.innerHTML='';for(const p of resultSortPeople(state.people,byPerson)){const seat=byPerson.get(p.id),hay=(p.name+' '+p.group+' '+(seat||'')).toLowerCase();if(q&&!hay.includes(q))continue;if(resultFilter.group!=='all'&&p.group!==resultFilter.group)continue;if(seat){const b=document.createElement('button');b.className='result-person-row';b.innerHTML='<strong>'+esc(p.name)+'</strong><span>'+esc(p.group||'ללא קבוצה')+' · מקום '+esc(seat)+'</span>';b.onclick=()=>{selectedSeat=seat;render();paintModePanel()};box.append(b)}else{const d=document.createElement('div');d.className='unassigned-row';d.innerHTML='<strong>'+esc(p.name)+'</strong><span>'+esc(p.group||'ללא קבוצה')+'</span>';un.append(d)}}if(!box.children.length)box.innerHTML='<p class="muted">אין תוצאות להצגה.</p>';if(!un.children.length)un.innerHTML='<p class="muted">אין משתתפים שממתינים לשיבוץ.</p>'}function setAssignmentBusy(on,label='משבץ…'){for(const id of ['autoAssign','autoAssignPrimary','autoAssignLinked']){const b=$('#'+id);if(!b)continue;if(on){if(!b.dataset.busyText)b.dataset.busyText=b.textContent;b.classList.add('is-busy');b.disabled=true;b.innerHTML='<span class="button-spinner"></span><span>'+label+'</span>'}else{b.classList.remove('is-busy');b.disabled=false;if(b.dataset.busyText){b.textContent=b.dataset.busyText;delete b.dataset.busyText}}}}
function nextFrame(){return new Promise(resolve=>requestAnimationFrame(()=>resolve()))}
async function withAssignmentBusy(fn,label='משבץ…'){setAssignmentBusy(true,label);await nextFrame();try{return await fn()}finally{setAssignmentBusy(false)}}
function setExportProgress(show,title='',text=''){const box=$('#exportProgress');if(!box)return;box.classList.toggle('hidden',!show);if(title)$('#exportProgressTitle').textContent=title;if(text!==undefined)$('#exportProgressText').textContent=text}
function exportCanvasScale(width,height){const maxDim=12000,maxPixels=64000000,target=2;return Math.max(.5,Math.min(target,maxDim/Math.max(width,height),Math.sqrt(maxPixels/(width*height))))}
