async function renderHallPngCanvas(){const logicalW=state.hall.gridWidth*CELL,logicalH=state.hall.gridHeight*CELL,scale=exportCanvasScale(logicalW,logicalH),canvasOut=document.createElement('canvas');canvasOut.width=Math.max(1,Math.round(logicalW*scale));canvasOut.height=Math.max(1,Math.round(logicalH*scale));const ctx=canvasOut.getContext('2d',{alpha:false});ctx.scale(scale,scale);ctx.fillStyle='#090d14';ctx.fillRect(0,0,logicalW,logicalH);ctx.strokeStyle='#1c2636';ctx.lineWidth=.6;for(let x=0;x<=state.hall.gridWidth;x++){ctx.beginPath();ctx.moveTo(x*CELL,0);ctx.lineTo(x*CELL,logicalH);ctx.stroke()}for(let y=0;y<=state.hall.gridHeight;y++){ctx.beginPath();ctx.moveTo(0,y*CELL);ctx.lineTo(logicalW,y*CELL);ctx.stroke()}const blocked=blockedKeySet();let done=0,total=Math.max(1,state.areas.reduce((n,a)=>n+a.cells.length,0)+seatRecords().length);for(const a of state.areas){ctx.fillStyle=colors[a.type]||colors.empty;ctx.globalAlpha=(a.type==='chair'||a.type==='benches')?.28:.34;for(const c of a.cells){ctx.fillRect(c.x*CELL+1,c.y*CELL+1,CELL-2,CELL-2);done++;if(done%500===0){setExportProgress(true,'מייצא את כל האולם…',Math.round(done/total*100)+'%');await nextFrame()}}ctx.globalAlpha=1;if(state.settings.showAreaLabels&&a.cells.length){const xs=a.cells.map(c=>c.x),ys=a.cells.map(c=>c.y),cx=(Math.min(...xs)+Math.max(...xs)+1)/2*CELL,cy=(Math.min(...ys)+Math.max(...ys)+1)/2*CELL;ctx.font='bold 11px Arial';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillStyle='#ffffff';ctx.strokeStyle='#000000';ctx.lineWidth=3;ctx.strokeText(a.name,cx,cy);ctx.fillText(a.name,cx,cy)}}for(const s of seatRecords()){const pid=assignmentForSeat(s),p=personById(pid),x=s.cell.x*CELL+5,y=s.cell.y*CELL+5,w=CELL-10,h=CELL-10;ctx.globalAlpha=1;ctx.fillStyle=s.blocked?'#050505':p?groupColor(p.group):'#293348';ctx.strokeStyle=s.blocked?'#4b5563':p?'#d7e8ff':'#64748b';ctx.lineWidth=1;roundedRect(ctx,x,y,w,h,4);ctx.fill();ctx.stroke();if(state.settings.showSeatNumbers){ctx.fillStyle='#ffffff';ctx.font='bold 7px Arial';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(String(s.number),x+w/2,y+h/2)}if(p){ctx.font='6px Arial';ctx.fillStyle='#ffffff';const label=p.name.length>12?p.name.slice(0,11)+'…':p.name;ctx.fillText(label,x+w/2,y+h+5)}done++;if(done%500===0){setExportProgress(true,'מייצא את כל האולם…',Math.round(done/total*100)+'%');await nextFrame()}}setExportProgress(true,'מסיים תמונה…','100%');await nextFrame();return canvasOut}
async function downloadHallPng(filename){setExportProgress(true,'מכין תמונת אולם…','0%');try{const out=await renderHallPngCanvas(),blob=await new Promise(resolve=>out.toBlob(resolve,'image/png'));if(!blob)throw Error('PNG');const a=document.createElement('a'),u=URL.createObjectURL(blob);a.href=u;a.download=safeFileName(filename)+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}finally{setExportProgress(false)}}
