function downloadBackup(){save();const payload={format:'seating-studio-workspace-v1',workspace:portfolio,activeState:state},a=document.createElement('a'),u=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));a.href=u;a.download=safeFileName(state.project.name)+'-workspace-backup.json';a.click();URL.revokeObjectURL(u)}$('#backup').onclick=downloadBackup;$('#restore').onclick=()=>$('#fileInput').click();$('#fileInput').onchange=async e=>{if(!e.target.files||!e.target.files[0])return;try{const d=JSON.parse(await e.target.files[0].text());if(d?.workspace){const restored=normalizeWorkspace(d.workspace);if(!restored)throw Error();portfolio=restored;persistWorkspace();const p=activeWorkspaceProject(),h=activeWorkspaceHall(p);applyWorkspaceHall(p,h);setMode('build');return}if(!Array.isArray(d.areas))throw Error();snapshot('שחזור מגיבוי');state.areas=d.areas.map(a=>({...a,type:a.type==='seats'?'chair':a.type})).filter(a=>AREA_TYPES.has(a.type)&&Array.isArray(a.cells));state.hall=normalizeHall(d.hall);state.project={...DEFAULT_PROJECT,...(d.project||{}),hallName:d.project?.hallName||d.hall?.name||DEFAULT_PROJECT.hallName};state.people=Array.isArray(d.people)?d.people:[];state.assignments=d.assignments&&typeof d.assignments==='object'?d.assignments:{};state.groupPriorities=d.groupPriorities&&typeof d.groupPriorities==='object'?d.groupPriorities:{};state.groupColors=d.groupColors&&typeof d.groupColors==='object'?d.groupColors:{};state.settings={...DEFAULT_SETTINGS,...(d.settings||{})};state.blockedSeats=Array.isArray(d.blockedSeats)?d.blockedSeats.filter(c=>Number.isInteger(c?.x)&&Number.isInteger(c?.y)):[];splitDisconnectedAreas();migrateAssignmentState();selected=null;applyGridSize();applySettings();save();render();renderPeople();fitContent()}catch{alert('קובץ גיבוי לא תקין')}};$('#reset').onclick=()=>{if(confirm('לאפס את האולם הנוכחי? המבנה והשיבוצים באולם יימחקו, אך הפרויקט, המשתתפים ושאר האולמות יישארו.')){snapshot('איפוס אולם');state.areas=[];state.assignments={};state.assignmentSchema=2;state.blockedSeats=[];state.hall={name:state.project.hallName||'אולם',version:9,gridWidth:40,gridHeight:28};selected=null;selectedPerson=null;selectedSeat=null;selectedSeats.clear();highlightedGroup=null;assignFilter={status:'all',group:'all',area:'all',query:''};resultFilter={status:'all',group:'all',query:'',sort:'seat'};$('#gridWidth').value=40;$('#gridHeight').value=28;applyGridSize();applySettings();save();render();renderPeople();renderGroupLegend();fitContent()}};$('#settingsButton').onclick=openSettings;
