if(!restoreLocal())state.settings=loadDefaultSettings();initWorkspace();normalizeSettings();normalizeProject();normalizeGroupPriorities();normalizeGroupColors();applyGridSize();applySettings();updateHistoryButtons();render();renderPeople();renderGroupPriorities();renderGroupLegend();setAssignSidePanel('overview');setMode('build');requestAnimationFrame(()=>requestAnimationFrame(fitContent));
window.addEventListener('beforeprint',renderPrintSheet);viewport.addEventListener('scroll',()=>{updateScrollExtent();scheduleGridDraw()});window.addEventListener('resize',()=>{fitContent();updateScrollExtent();scheduleGridDraw()});
document.addEventListener('keydown',e=>{const cmd=e.ctrlKey||e.metaKey,tag=e.target?.tagName?.toLowerCase(),editing=tag==='input'||tag==='textarea'||tag==='select'||e.target?.isContentEditable;if(e.key==='Escape'){if($('#settingsDialog').open){$('#settingsDialog').close();return}if(mode==='assign'){selectedSeats.clear();highlightedGroup=null;render();renderGroupLegend()}return}if(editing)return;if(cmd&&e.key.toLowerCase()==='a'&&mode==='assign'){e.preventDefault();selectSeatNumbers(visibleAssignmentSeats(),true);return}if(cmd&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redoAction():undoAction();return}if(cmd&&e.key.toLowerCase()==='y'){e.preventDefault();redoAction();return}if(cmd&&e.key==='0'){e.preventDefault();fitContent();return}if(cmd&&e.key.toLowerCase()==='s'){e.preventDefault();downloadBackup();return}if(cmd&&e.key.toLowerCase()==='p'&&mode==='result'){e.preventDefault();window.print();return}if(cmd&&e.key===','){e.preventDefault();openSettings();return}if(!cmd&&e.key==='1')setMode('build');else if(!cmd&&e.key==='2')setMode('assign');else if(!cmd&&e.key==='3')setMode('result')});
